      dd14Note3: 'यदि वर्ष के दौरान वैवाहिक स्थिति बदलती है, तो लेखाकार को तदनुसार सूचित किया जाता है।',
      dd14MultiEmployerNote: 'यदि आप एक से अधिक नियोक्ताओं के लिए काम करते हैं, तो प्राथमिक नियोक्ता वह है जिसे आप कानूनी भत्ता और शेष कटौतियाँ देने के लिए चुनते हैं, जबकि अन्य नियोक्ता उसके हकदार नहीं हैं, सिवाय सेवानिवृत्ति कटौती या सामाजिक सुरक्षा हिस्से के जो हर नियोक्ता द्वारा काटा जाता है।',
      dd14MergeNote: 'आयों का विलय केवल तभी अनुमत है जब पति-पत्नी में से किसी एक की वार्षिक आय 2,500,000 दीनार से कम हो और संबंधित वर्ष की 31 जनवरी से पहले विलय के लिए आवेदन प्रस्तुत किया जाए; इस मामले में कर को अधिक आय वाले पति-पत्नी के वेतन से काटा जाना चाहिए, और दूसरे पति-पत्नी के वेतन से कोई कर नहीं काटा जाता है।',
      dd14FilledByAccountant: 'आयकर गणना लेखाकार द्वारा भरी जाती है (वर्ष के अंत में)',
      incomeTableIncomeHeader: 'आय',
      dinarHeader: 'दीनार',
      dd14Row1a: '1 a) वर्ष के दौरान भुगतान किया गया कुल वेतन और मजदूरी',
      dd14Row1b: '1 b) निजी क्षेत्र के कर्मचारियों के लिए वर्ष के दौरान भुगतान किए गए कपड़े, आवास, रहने, भोजन, परिवहन और खतरे के भत्तों का कुल, और राज्य, सार्वजनिक और मिश्रित क्षेत्र के कर्मचारियों द्वारा प्राप्त कुल भत्ते',
      dd14Row1c: '1 c) सभी पूर्णतः कर योग्य भत्ते',
