      dd14Row2c: '2 c) आयकर कानून (113) 1982 ई. की धारा (8) में प्रदान की गई कटौतियाँ *',
      dd14Row2d: '2 d) आवास, भोजन, रहने, खतरे, परिवहन और कपड़ों के भत्ते (30% छूट)',
