      dd14Page2Note2: 'यदि फ़ॉर्म उन पति-पत्नी में से किसी एक से संबंधित है जिसकी वार्षिक आय 2,500,000 दीनार से कम है और उसकी आय दूसरे पति-पत्नी की आय के साथ विलय की गई है, तो इस फ़ॉर्म की जानकारी दूसरे पति-पत्नी के प्राथमिक नियोक्ता को भेजी जाती है ताकि उस वर्ष के लिए प्रत्यक्ष कटौती कर की सही राशि की गणना की जा सके।',
